package com.integration.service.solar.impl;

import com.integration.model.dto.LeadSapRequest;
import com.integration.model.dto.SapCreateResponse;
import com.integration.service.SapService;
import com.integration.service.solar.SolarLeadSquaredService;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Captor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.ResponseEntity;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyList;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class SolarLeadServiceImplTest {

    @Mock
    private SolarLeadSquaredService solarLeadSquaredService;

    @Mock
    private SapService sapService;

    @InjectMocks
    private SolarLeadServiceImpl solarLeadService;

    @Captor
    private ArgumentCaptor<LeadSapRequest> leadSapRequestCaptor;

    @Test
    void shouldProcessLeadAndCreateSapCustomerWhenStageIsDealConverted() throws Exception {
        // Arrange
        Map<String, Object> lead = buildLead("prospect-001", "Deal Converted", "", "John", "9876543210");
        Map<String, Object> lsqResponse = Map.of("Leads", List.of(lead));
        when(solarLeadSquaredService.getLeadsInBulkByIds(anyList()))
                .thenReturn(ResponseEntity.ok(lsqResponse));
        when(sapService.createCustomer(any())).thenReturn(buildSapSuccessResponse("SAP-001"));

        // Act
        boolean result = solarLeadService.processLeadIds(List.of("prospect-001"));

        // Assert
        assertThat(result).isTrue();
        verify(sapService).createCustomer(leadSapRequestCaptor.capture());
        LeadSapRequest captured = leadSapRequestCaptor.getValue();
        assertThat(captured.getProspectId()).isEqualTo("prospect-001");
        assertThat(captured.getName()).isEqualTo("John");
        assertThat(captured.getMobile()).isEqualTo("9876543210");
    }

    @Test
    void shouldUpdateLeadInLsqWithSapCodeAfterSuccessfulCreation() throws Exception {
        // Arrange
        Map<String, Object> lead = buildLead("prospect-002", "Deal Converted", "", "Jane", "9123456780");
        Map<String, Object> lsqResponse = Map.of("Leads", List.of(lead));
        when(solarLeadSquaredService.getLeadsInBulkByIds(anyList()))
                .thenReturn(ResponseEntity.ok(lsqResponse));
        when(sapService.createCustomer(any())).thenReturn(buildSapSuccessResponse("SAP-999"));

        // Act
        solarLeadService.processLeadIds(List.of("prospect-002"));

        // Assert — SAP code written back to LeadSquared
        verify(solarLeadSquaredService).updateLeadSapCode(eq("prospect-002"), eq("SAP-999"));
    }

    @Test
    void shouldSkipLeadWhenCustomerCodeAlreadyExists() throws Exception {
        // Arrange — lead already has a SAP customer code
        Map<String, Object> lead = buildLead("prospect-003", "Deal Converted", "EXISTING-SAP", "Bob", "9000000000");
        Map<String, Object> lsqResponse = Map.of("Leads", List.of(lead));
        when(solarLeadSquaredService.getLeadsInBulkByIds(anyList()))
                .thenReturn(ResponseEntity.ok(lsqResponse));

        // Act
        boolean result = solarLeadService.processLeadIds(List.of("prospect-003"));

        // Assert
        assertThat(result).isTrue();
        verify(sapService, never()).createCustomer(any());
        verify(solarLeadSquaredService, never()).updateLeadSapCode(anyString(), anyString());
    }

    @Test
    void shouldSkipLeadWhenStageIsNotDealConverted() throws Exception {
        // Arrange
        Map<String, Object> lead = buildLead("prospect-004", "Lead Stage", "", "Alice", "9111111111");
        Map<String, Object> lsqResponse = Map.of("Leads", List.of(lead));
        when(solarLeadSquaredService.getLeadsInBulkByIds(anyList()))
                .thenReturn(ResponseEntity.ok(lsqResponse));

        // Act
        boolean result = solarLeadService.processLeadIds(List.of("prospect-004"));

        // Assert
        assertThat(result).isTrue();
        verify(sapService, never()).createCustomer(any());
    }

    @Test
    void shouldReturnFalseWhenLsqResponseIsNotSuccessful() throws Exception {
        // Arrange
        when(solarLeadSquaredService.getLeadsInBulkByIds(anyList()))
                .thenReturn(ResponseEntity.status(500).build());

        // Act
        boolean result = solarLeadService.processLeadIds(List.of("prospect-005"));

        // Assert
        assertThat(result).isFalse();
        verify(sapService, never()).createCustomer(any());
    }

    @Test
    void shouldReturnFalseWhenLeadsKeyAbsentInResponse() throws Exception {
        // Arrange — response body has no "Leads" key
        Map<String, Object> lsqResponse = Map.of("Status", "Success");
        when(solarLeadSquaredService.getLeadsInBulkByIds(anyList()))
                .thenReturn(ResponseEntity.ok(lsqResponse));

        // Act
        boolean result = solarLeadService.processLeadIds(List.of("prospect-006"));

        // Assert
        assertThat(result).isFalse();
        verify(sapService, never()).createCustomer(any());
    }

    @Test
    void shouldContinueProcessingRemainingLeadsWhenOneLeadFails() throws Exception {
        // Arrange — two leads; SAP throws for first, succeeds for second
        Map<String, Object> lead1 = buildLead("prospect-007", "Deal Converted", "", "Fail Lead", "9000000001");
        Map<String, Object> lead2 = buildLead("prospect-008", "Deal Converted", "", "Good Lead", "9000000002");
        Map<String, Object> lsqResponse = new HashMap<>();
        lsqResponse.put("Leads", List.of(lead1, lead2));
        when(solarLeadSquaredService.getLeadsInBulkByIds(anyList()))
                .thenReturn(ResponseEntity.ok(lsqResponse));
        when(sapService.createCustomer(any()))
                .thenThrow(new RuntimeException("SAP timeout"))
                .thenReturn(buildSapSuccessResponse("SAP-002"));

        // Act
        boolean result = solarLeadService.processLeadIds(List.of("prospect-007", "prospect-008"));

        // Assert — second lead still processed despite first failing
        assertThat(result).isTrue();
        verify(solarLeadSquaredService).updateLeadSapCode(eq("prospect-008"), eq("SAP-002"));
        verify(solarLeadSquaredService, never()).updateLeadSapCode(eq("prospect-007"), anyString());
    }

    @Test
    void shouldNotCallUpdateWhenSapResponseHasNoChangeNumber() throws Exception {
        // Arrange — SAP responds but without a Change_Number
        Map<String, Object> lead = buildLead("prospect-009", "Deal Converted", "", "No Code", "9000000003");
        Map<String, Object> lsqResponse = Map.of("Leads", List.of(lead));
        when(solarLeadSquaredService.getLeadsInBulkByIds(anyList()))
                .thenReturn(ResponseEntity.ok(lsqResponse));
        when(sapService.createCustomer(any()))
                .thenReturn(SapCreateResponse.builder().status(0).changeNumber(null).build());

        // Act
        solarLeadService.processLeadIds(List.of("prospect-009"));

        // Assert — no update call since no SAP code was returned
        verify(solarLeadSquaredService, never()).updateLeadSapCode(anyString(), anyString());
    }

    // Helper — builds a lead map matching the flat structure returned by getLeadsInBulkByIds
    private Map<String, Object> buildLead(String prospectId, String stage,
                                           String customerCode, String name, String phone) {
        Map<String, Object> lead = new HashMap<>();
        lead.put("ProspectID", prospectId);
        lead.put("ProspectStage", stage);
        lead.put("mx_Customer_Code", customerCode);
        lead.put("FirstName", name);
        lead.put("Phone", phone);
        lead.put("mx_PAN_No", "ABCDE1234F");
        lead.put("EmailAddress", name.toLowerCase().replace(" ", "") + "@example.com");
        lead.put("mx_Street1", "123 Test Street");
        lead.put("mx_City", "Mumbai");
        lead.put("mx_States", "Maharashtra");
        lead.put("mx_Zip", "400001");
        return lead;
    }

    // Helper — builds a SAP success response DTO
    private SapCreateResponse buildSapSuccessResponse(String changeNumber) {
        return SapCreateResponse.builder()
                .status(0)
                .changeNumber(changeNumber)
                .build();
    }
}

