package com.integration.service.impl;

import com.integration.model.solar.DistrictPlantCodeMapping;
import com.integration.model.solar.StateCodeMapping;
import com.integration.model.dto.LeadSapRequest;
import com.integration.model.dto.SapCreateResponse;
import com.integration.repository.APILoggerRepository;
import com.integration.repository.solar.DistrictPlantCodeMappingRepository;
import com.integration.repository.solar.StateCodeMappingRepository;
import com.integration.util.RestUtils;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.ResponseEntity;
import org.springframework.test.util.ReflectionTestUtils;

import java.util.HashMap;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class SapServiceImplTest {

    @Mock
    private RestUtils restUtils;

    @Mock
    private APILoggerRepository apiLoggerRepository;

    @Mock
    private StateCodeMappingRepository stateCodeMappingRepository;

    @Mock
    private DistrictPlantCodeMappingRepository districtPlantCodeMappingRepository;

    @InjectMocks
    private SapServiceImpl sapService;

    @BeforeEach
    void setUp() {
        ReflectionTestUtils.setField(sapService, "sapApiUrl", "https://sap.test.com/api/customer");
        ReflectionTestUtils.setField(sapService, "sapAuthorization", "Basic dGVzdA==");
    }

    // --- createCustomer ---

    @Test
    void shouldReturnSapResponseWithChangeNumberOnSuccess() throws Exception {
        // Arrange
        LeadSapRequest request = buildRequest("prospect-001", "John", "9876543210", "Maharashtra", "Pune");
        Map<String, Object> record = Map.of("Change_Number", "SAP-001");
        Map<String, Object> body = new HashMap<>();
        body.put("status", 0);
        body.put("Record", record);
        when(stateCodeMappingRepository.findByStateIgnoreCase("Maharashtra")).thenReturn(null);
        when(districtPlantCodeMappingRepository.findByDistrictIgnoreCase("Pune")).thenReturn(null);
        when(restUtils.postV2(anyString(), anyString(), any())).thenReturn(ResponseEntity.ok(body));

        // Act
        SapCreateResponse result = sapService.createCustomer(request);

        // Assert
        assertThat(result).isNotNull();
        assertThat(result.getStatus()).isEqualTo(0);
        assertThat(result.getChangeNumber()).isEqualTo("SAP-001");
    }

    @Test
    void shouldReturnNullWhenSapApiThrowsException() throws Exception {
        // Arrange
        LeadSapRequest request = buildRequest("prospect-002", "Jane", "9000000000", "Gujarat", "Surat");
        when(stateCodeMappingRepository.findByStateIgnoreCase(anyString())).thenReturn(null);
        when(districtPlantCodeMappingRepository.findByDistrictIgnoreCase(anyString())).thenReturn(null);
        when(restUtils.postV2(anyString(), anyString(), any())).thenThrow(new RuntimeException("SAP unavailable"));

        // Act
        SapCreateResponse result = sapService.createCustomer(request);

        // Assert — exception is caught internally, returns null (no response body)
        assertThat(result).isNull();
    }

    @Test
    void shouldReturnResponseWithNoChangeNumberWhenStatusIsNonZero() throws Exception {
        // Arrange
        LeadSapRequest request = buildRequest("prospect-003", "Bob", "9111111111", "Delhi", "Delhi");
        Map<String, Object> body = new HashMap<>();
        body.put("status", 1);
        when(stateCodeMappingRepository.findByStateIgnoreCase(anyString())).thenReturn(null);
        when(districtPlantCodeMappingRepository.findByDistrictIgnoreCase(anyString())).thenReturn(null);
        when(restUtils.postV2(anyString(), anyString(), any())).thenReturn(ResponseEntity.ok(body));

        // Act
        SapCreateResponse result = sapService.createCustomer(request);

        // Assert
        assertThat(result).isNotNull();
        assertThat(result.getStatus()).isEqualTo(1);
        assertThat(result.getChangeNumber()).isNull();
    }

    @Test
    void shouldLogApiCallAfterCreatingCustomer() throws Exception {
        // Arrange
        LeadSapRequest request = buildRequest("prospect-004", "Alice", "9222222222", "Karnataka", "Bangalore");
        Map<String, Object> body = new HashMap<>();
        body.put("status", 0);
        body.put("Record", Map.of("Change_Number", "SAP-002"));
        when(stateCodeMappingRepository.findByStateIgnoreCase(anyString())).thenReturn(null);
        when(districtPlantCodeMappingRepository.findByDistrictIgnoreCase(anyString())).thenReturn(null);
