package com.integration.util;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

import java.util.Calendar;
import java.util.Date;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

class UtilsTest {

    // --- transformMobileNumber ---

    @ParameterizedTest(name = "\"{0}\" -> \"{1}\"")
    @CsvSource({
            "+91-9876543210, 9876543210",
            "91-9876543210,  9876543210",
            "+919876543210,  9876543210",
            "9876543210,     9876543210",
            "0091-123456789, 0091-123456789"
    })
    void shouldStripIndianCallingCodePrefixes(String input, String expected) {
        assertThat(Utils.transformMobileNumber(input.trim())).isEqualTo(expected.trim());
    }

    @Test
    void shouldReturnNullWhenMobileNumberIsNull() {
        assertThat(Utils.transformMobileNumber(null)).isNull();
    }

    @Test
    void shouldReturnEmptyStringWhenMobileNumberIsEmpty() {
        assertThat(Utils.transformMobileNumber("")).isEqualTo("");
    }

    // --- escapeSpecialCharacters ---

    @Test
    void shouldReturnValueUnchangedWhenNoSpecialCharacters() {
        assertThat(Utils.escapeSpecialCharacters("Hello World")).isEqualTo("Hello World");
    }

    @Test
    void shouldWrapInQuotesAndReplaceCommaWhenValueContainsComma() {
        // commas replaced with semicolons and wrapped in quotes
        assertThat(Utils.escapeSpecialCharacters("Mumbai, Maharashtra")).isEqualTo("\"Mumbai; Maharashtra\"");
    }

    @Test
    void shouldEscapeDoubleQuotesAndWrapValue() {
        assertThat(Utils.escapeSpecialCharacters("say \"hello\"")).isEqualTo("\"say \"\"hello\"\"\"");
    }

    @Test
    void shouldReplaceNewlinesWithSpace() {
        assertThat(Utils.escapeSpecialCharacters("line1\nline2")).isEqualTo("line1 line2");
    }

    @Test
    void shouldReturnEmptyStringWhenInputIsNull() {
        assertThat(Utils.escapeSpecialCharacters(null)).isEqualTo("");
    }

    // --- convertToCSV ---

    @Test
    void shouldJoinPlainValuesWithCommas() {
        assertThat(Utils.convertToCSV(new String[]{"John", "Doe", "Mumbai"}))
                .isEqualTo("John,Doe,Mumbai");
    }

    @Test
    void shouldEscapeValuesContainingCommasWhenConverting() {
        assertThat(Utils.convertToCSV(new String[]{"John", "Mumbai, MH", "400001"}))
                .isEqualTo("John,\"Mumbai; MH\",400001");
    }

    // --- formatDate ---

    @Test
    void shouldFormatDateWithGivenPattern() {
        Calendar cal = Calendar.getInstance();
        cal.set(2024, Calendar.MARCH, 15, 0, 0, 0);
        Date date = cal.getTime();

        assertThat(Utils.formatDate(date, "yyyy-MM-dd")).isEqualTo("2024-03-15");
    }

    @Test
    void shouldFormatDateWithSlashPattern() {
        Calendar cal = Calendar.getInstance();
        cal.set(2024, Calendar.JANUARY, 5, 0, 0, 0);
        Date date = cal.getTime();

        assertThat(Utils.formatDate(date, "dd/MM/yyyy")).isEqualTo("05/01/2024");
    }

    // --- getDateParts ---

    @Test
    void shouldExtractYearMonthAndDayFromDate() {
        Calendar cal = Calendar.getInstance();
        cal.set(2024, Calendar.MARCH, 7);
        Date date = cal.getTime();

        Map<String, String> parts = Utils.getDateParts(date);

        assertThat(parts.get("year")).isEqualTo("2024");
        assertThat(parts.get("month")).isEqualTo("03");
        assertThat(parts.get("day")).isEqualTo("07");
    }

    @Test
    void shouldZeroPadSingleDigitMonthAndDay() {
        Calendar cal = Calendar.getInstance();
        cal.set(2024, Calendar.JANUARY, 5);
        Date date = cal.getTime();

        Map<String, String> parts = Utils.getDateParts(date);

        assertThat(parts.get("month")).isEqualTo("01");
        assertThat(parts.get("day")).isEqualTo("05");
    }
}

