package com.integration.controller.solar;

import com.integration.service.solar.SolarLeadSquaredService;
import lombok.RequiredArgsConstructor;
import lombok.extern.log4j.Log4j2;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Date;


@RestController
@Log4j2
@RequestMapping("/solarleadsquare")
@RequiredArgsConstructor
public class SolarLeadsquareController {

    private final SolarLeadSquaredService solarLeadSquaredService;

    @GetMapping(value = "/getLeadsByStage")
    public Object getLeadsByStage() {
        ResponseEntity<Object> response = solarLeadSquaredService.getLeadsByStage();
        return response.getBody();
    }

    @GetMapping(value = "/getRecentlyModifiedLeads")
    public Object getRecentlyModifiedLeads(@RequestParam @DateTimeFormat(pattern = "yyyy-MM-dd HH:mm:ss") Date fromDate,
                                           @RequestParam @DateTimeFormat(pattern = "yyyy-MM-dd HH:mm:ss") Date toDate) {
        return solarLeadSquaredService.getRecentlyModifiedLeads(fromDate, toDate);
    }

    @PostMapping(value = "/updateLeadsInBulk")
    public boolean updateLeadsInBulk(@RequestBody java.util.Map<String, Object> payload) {
        return solarLeadSquaredService.updateLeadsInBulk(payload);
    }
}

