    private String createRecentlyModifiedLeadsPayload(int pageIndex, int pageSize, String fromDateString, String toDateString){
        String jsonBody = "{\n" +
                "\t\"Parameter\": {\n" +
                "        \"FromDate\": \"" + fromDateString + "\",\n" +
                "        \"ToDate\": \"" + toDateString + "\"\n" +
                "    },\n" +
                "    \"Columns\":{\"Include_CSV\":\"ProspectID, Phone, FirstName, LastName, EmailAddress, mx_Street1, mx_City, mx_States, mx_Zip, mx_PAN_No, mx_Customer_Code \"},\n" +
                "    \"Paging\": {\n" +
                "        \"PageIndex\": " + pageIndex + ",\n" +
                "        \"PageSize\":  " + pageSize + "\n" +
                "    }\n" +
                "}";
        return jsonBody;
    }

    @Override
    public List<Map<String, Object>> getRecentlyModifiedLeads(Date fromDate, Date toDate) throws Exception {
        String fromDateString = Utils.formatDate(fromDate, "yyyy-MM-dd HH:mm:ss");
        String toDateString = Utils.formatDate(toDate, "yyyy-MM-dd HH:mm:ss");
        int pageIndex = 1;
        int pageSize = 500;
        int processedRecords = 0;
        int totalRecords = Integer.MAX_VALUE;

        String body = createRecentlyModifiedLeadsPayload(pageIndex, pageSize, fromDateString, toDateString);
        Map<String, String> headers = createHeaders();
        ResponseEntity<Map> response = restUtils.postV2(lsqRecentlyModifiedUrl, body, headers);

        log.info("Fetching recently modified leads from LeadSquared from " + fromDate + " to " + toDate);

        DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        //String fromDateString = dateFormat.format(fromDate);
        //String toDateString = dateFormat.format(toDate);

        logApiCall("Get Recently Modified Leads", lsqRecentlyModifiedUrl, body, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        if (response.getStatusCode().is2xxSuccessful() && response.getBody() != null) {
            Object responseBody = response.getBody();
            if (responseBody instanceof List) {
                return (List<Map<String, Object>>) responseBody;
            } else if (responseBody instanceof Map) {
                Map<String, Object> bodyMap = (Map<String, Object>) responseBody;
                if (bodyMap.containsKey("Leads")) {
                    return (List<Map<String, Object>>) bodyMap.get("Leads");
                }
            }
            log.warn("Unexpected response format for recently modified leads. Response body: " + responseBody);
            return null;
        } else {
            log.error("Failed to fetch recently modified leads from LeadSquared. Status: " + response.getStatusCode() + " Response: " + response.getBody());
            return null;
        }
    }

    @Override
    public ResponseEntity<Map> getRecentlyModifiedLeadsByPayload(String body) throws Exception {
        Map<String, String> headers = createHeaders();
        ResponseEntity<Map> response = restUtils.postV2(lsqRecentlyModifiedUrl, body, headers);

        logApiCall("Get Recently Modified Leads", lsqRecentlyModifiedUrl, body, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        return response;
    }

    @Override
    public boolean updateLeadsInBulk(Map<String, Object> payload) throws Exception {
        String url = lsqBulkUpdateLeadUrl; //+ "?accessKey=" + solarLsqAccessKey + "&secretKey=" + solarLsqSecretKey;
        log.info("Updating leads in bulk in LeadSquared");

        com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
        String jsonPayload = mapper.writeValueAsString(payload);

        ResponseEntity<Map> response = restUtils.postV2(url, jsonPayload, createHeaders());

        logApiCall("Update Leads In Bulk", url, jsonPayload, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        if (response.getStatusCode() == HttpStatus.OK && response.getBody() != null) {
            Map<String, Object> body = response.getBody();
            if (body.get("Status") != null && body.get("Status").toString().equalsIgnoreCase("Success")) {
                log.info("Successfully updated leads in bulk.");
                return true;
            }
        }
        log.error("Failed to update leads in bulk. Response: " + response);
        return false;
    }

    @Override
    public boolean updateLeadsInBulkV2(Map<String, Object> payload) throws Exception {
        String url = lsqBulkUpdateLeadV2Url;
        log.info("Updating leads in bulk (v2) in LeadSquared with " + (payload != null ? payload.size() : 0) + " records");

        com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
        String jsonPayload = mapper.writeValueAsString(payload);
        ResponseEntity<Map> response = restUtils.postV2(url, jsonPayload, createHeaders());

        logApiCall("Update Leads In Bulk V2", url, jsonPayload, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        if (response.getStatusCode() == HttpStatus.OK && response.getBody() != null) {
            Map<String, Object> body = response.getBody();
            if (body.get("Status") != null && ((Map)body.get("Status")).get("Message")!=null && ((Map)body.get("Status")).get("Message").toString().equalsIgnoreCase("Processed")) {
                log.info("Successfully updated leads in bulk (v2).");
                return true;
            }
        }
        log.error("Failed to update leads in bulk (v2). Response: " + response);
        return false;
    }

    private String createLeadsBulkByIdsPayload(List<String> leadIds) {
        StringBuilder sb = new StringBuilder();
        sb.append("{\n");
        sb.append("  \"SearchParameters\": {\n");
        sb.append("    \"LeadIds\": [\n");
        for (int i = 0; i < leadIds.size(); i++) {
            sb.append("      \"").append(leadIds.get(i)).append("\"");
            if (i < leadIds.size() - 1) {
                sb.append(",");
            }
            sb.append("\n");
        }
        sb.append("    ]\n");
        sb.append("  },\n");
        sb.append("  \"Columns\": {\n");
        sb.append("    \"Include_CSV\": \"ProspectID, ProspectStage, Phone, FirstName, LastName, EmailAddress, mx_Street1, mx_City, mx_States, mx_Zip, mx_PAN_No, mx_Customer_Code\"\n");
        sb.append("  },\n");
        sb.append("  \"Paging\": {\n");
        sb.append("    \"PageIndex\": 1,\n");
        sb.append("    \"PageSize\": 1000\n");
        sb.append("  }\n");
        sb.append("}");
        return sb.toString();
    }

    @Override
    public ResponseEntity<Map> getLeadsInBulkByIds(List<String> leadIds) throws Exception {
        String url = lsqLeadsGetByIdsUrl;
        String payload = createLeadsBulkByIdsPayload(leadIds);
        Map<String, String> headers = createHeaders();
        ResponseEntity<Map> response = restUtils.postV2(url, payload, headers);
        logApiCall("Get Leads In Bulk By IDs", url, payload, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");
        return response;
    }
}

package com.integration.service.impl;

import com.integration.model.solar.DistrictPlantCodeMapping;
import com.integration.model.solar.StateCodeMapping;
import com.integration.model.dto.LeadSapRequest;
import com.integration.model.dto.SapCreateResponse;
import com.integration.repository.APILoggerRepository;
import com.integration.repository.solar.DistrictPlantCodeMappingRepository;
import com.integration.repository.solar.StateCodeMappingRepository;
import com.integration.util.RestUtils;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.ResponseEntity;
import org.springframework.test.util.ReflectionTestUtils;

import java.util.HashMap;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class SapServiceImplTest {

    @Mock
    private RestUtils restUtils;

    @Mock
    private APILoggerRepository apiLoggerRepository;

    @Mock
    private StateCodeMappingRepository stateCodeMappingRepository;

    @Mock
    private DistrictPlantCodeMappingRepository districtPlantCodeMappingRepository;

    @InjectMocks
    private SapServiceImpl sapService;

    @BeforeEach
    void setUp() {
        ReflectionTestUtils.setField(sapService, "sapApiUrl", "https://sap.test.com/api/customer");
        ReflectionTestUtils.setField(sapService, "sapAuthorization", "Basic dGVzdA==");
    }

    // --- createCustomer ---

    @Test
    void shouldReturnSapResponseWithChangeNumberOnSuccess() throws Exception {
        // Arrange
        LeadSapRequest request = buildRequest("prospect-001", "John", "9876543210", "Maharashtra", "Pune");
        Map<String, Object> record = Map.of("Change_Number", "SAP-001");
        Map<String, Object> body = new HashMap<>();
        body.put("status", 0);
        body.put("Record", record);
        when(stateCodeMappingRepository.findByStateIgnoreCase("Maharashtra")).thenReturn(null);
        when(districtPlantCodeMappingRepository.findByDistrictIgnoreCase("Pune")).thenReturn(null);
        when(restUtils.postV2(anyString(), anyString(), any())).thenReturn(ResponseEntity.ok(body));

        // Act
        SapCreateResponse result = sapService.createCustomer(request);

        // Assert
        assertThat(result).isNotNull();
        assertThat(result.getStatus()).isEqualTo(0);
        assertThat(result.getChangeNumber()).isEqualTo("SAP-001");
    }

    @Test
    void shouldReturnNullWhenSapApiThrowsException() throws Exception {
        // Arrange
        LeadSapRequest request = buildRequest("prospect-002", "Jane", "9000000000", "Gujarat", "Surat");
        when(stateCodeMappingRepository.findByStateIgnoreCase(anyString())).thenReturn(null);
        when(districtPlantCodeMappingRepository.findByDistrictIgnoreCase(anyString())).thenReturn(null);
        when(restUtils.postV2(anyString(), anyString(), any())).thenThrow(new RuntimeException("SAP unavailable"));

        // Act
        SapCreateResponse result = sapService.createCustomer(request);

        // Assert — exception is caught internally, returns null (no response body)
        assertThat(result).isNull();
    }

    @Test
    void shouldReturnResponseWithNoChangeNumberWhenStatusIsNonZero() throws Exception {
        // Arrange
        LeadSapRequest request = buildRequest("prospect-003", "Bob", "9111111111", "Delhi", "Delhi");
        Map<String, Object> body = new HashMap<>();
        body.put("status", 1);
        when(stateCodeMappingRepository.findByStateIgnoreCase(anyString())).thenReturn(null);
        when(districtPlantCodeMappingRepository.findByDistrictIgnoreCase(anyString())).thenReturn(null);
        when(restUtils.postV2(anyString(), anyString(), any())).thenReturn(ResponseEntity.ok(body));

        // Act
        SapCreateResponse result = sapService.createCustomer(request);

        // Assert
        assertThat(result).isNotNull();
        assertThat(result.getStatus()).isEqualTo(1);
        assertThat(result.getChangeNumber()).isNull();
    }

    @Test
    void shouldLogApiCallAfterCreatingCustomer() throws Exception {
        // Arrange
        LeadSapRequest request = buildRequest("prospect-004", "Alice", "9222222222", "Karnataka", "Bangalore");
        Map<String, Object> body = new HashMap<>();
        body.put("status", 0);
        body.put("Record", Map.of("Change_Number", "SAP-002"));
        when(stateCodeMappingRepository.findByStateIgnoreCase(anyString())).thenReturn(null);
        when(districtPlantCodeMappingRepository.findByDistrictIgnoreCase(anyString())).thenReturn(null);
        when(restUtils.postV2(anyString(), anyString(), any())).thenReturn(ResponseEntity.ok(body));

        // Act
        sapService.createCustomer(request);

        // Assert — API call is logged to MongoDB
        verify(apiLoggerRepository).save(any());
    }

    // --- getStateCode ---

    @Test
    void shouldReturnStateCodeWhenStateFoundInRepository() throws Exception {
        // Arrange
        StateCodeMapping mapping = new StateCodeMapping();
        mapping.setState("Maharashtra");
        mapping.setStateCode("13");
        when(stateCodeMappingRepository.findByStateIgnoreCase("Maharashtra")).thenReturn(mapping);

        // Act
        String result = sapService.getStateCode("Maharashtra");

        // Assert
        assertThat(result).isEqualTo("13");
    }

    @Test
    void shouldReturnEmptyStringWhenStateNotFoundInRepository() throws Exception {
        // Arrange
        when(stateCodeMappingRepository.findByStateIgnoreCase("UnknownState")).thenReturn(null);

        // Act
        String result = sapService.getStateCode("UnknownState");

        // Assert
        assertThat(result).isEqualTo("");
    }

    // --- getPlantCode ---

    @Test
    void shouldReturnPlantCodeWhenDistrictFoundInRepository() throws Exception {
        // Arrange
        DistrictPlantCodeMapping mapping = new DistrictPlantCodeMapping();
        mapping.setDistrict("Pune");
        mapping.setPlantCode("PUN1");
        when(districtPlantCodeMappingRepository.findByDistrictIgnoreCase("Pune")).thenReturn(mapping);

        // Act
        String result = sapService.getPlantCode("Pune");

        // Assert
        assertThat(result).isEqualTo("PUN1");
    }

    @Test
    void shouldReturnEmptyStringWhenDistrictNotFoundInRepository() throws Exception {
        // Arrange
        when(districtPlantCodeMappingRepository.findByDistrictIgnoreCase("UnknownCity")).thenReturn(null);

        // Act
        String result = sapService.getPlantCode("UnknownCity");

        // Assert
        assertThat(result).isEqualTo("");
    }

    // Helper
    private LeadSapRequest buildRequest(String prospectId, String name, String mobile,
                                         String state, String city) {
        return LeadSapRequest.builder()
                .prospectId(prospectId)
                .name(name)
                .mobile(mobile)
                .email(name.toLowerCase() + "@example.com")
                .pan("ABCDE1234F")
                .address("123 Test Street")
                .city(city)
                .state(state)
                .pincode("400001")
                .build();
    }
}

